<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesItem;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesUidVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesListRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesRoleVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesVersionVO;

final class UserRoleAssignmentRolesVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        ));
        $ref = UserRoleAssignmentRolesVO::from($value);
        $this->assertEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )), $ref->value());
        $this->assertTrue(!!$ref->find('one'));
        $this->assertTrue(!$ref->find('other'));
        $current = new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            null,
            null,
        );
        $cloned = UserRoleAssignmentRolesVO::from([$current]);
        $clonedFilled = $cloned->getWithDefaults($ref);
        $clonedValue = $cloned->value();
        $clonedFilledValue = $clonedFilled->value();
        $this->assertNull($clonedValue->current()->getRole());
        $this->assertEquals(new RoleRef('one'), $clonedFilledValue->current()->getRole());
        $this->assertNull($clonedValue->current()->getVersion());
        $this->assertEquals(1, $clonedFilledValue->current()->getVersion());
        $other = UserRoleAssignmentRolesVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = UserRoleAssignmentRolesVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = UserRoleAssignmentRolesVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(UserRoleAssignmentRolesVO::class, 'fromUnsafe');
        $method->invoke(null, "bad");
    }
    public function test_equals(): void
    {
        $one = UserRoleAssignmentRolesVO::from(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )));
        $same = UserRoleAssignmentRolesVO::from(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )));
        $other = UserRoleAssignmentRolesVO::from(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('other'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('other')),
            UserRoleAssignmentRolesVersionVO::from(2)
        )));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_build_empty(): void
    {
        $errors = new ConstraintFailList();
        $temp = UserRoleAssignmentRolesVO::tryFrom([], $errors);
        $this->assertFalse($temp->value()->valid());
        $temp = UserRoleAssignmentRolesVO::tryFrom(null, $errors);
        $this->assertNull($temp->value());
    }
}
